    ('c01326ea-62d0-509c-b467-9d2770ee4e4b'::uuid, 40000),
    ('4f422092-020e-57a1-9feb-0c5a341034c4'::uuid, 70000),
    ('486b3c4f-a92e-5faf-bd05-00444519b0bc'::uuid, 120000),
    ('789ef4a9-b9f7-537b-8915-ca37ea2b28c8'::uuid, 250000),
    ('4c83e547-00bc-5b96-bea7-abb15b491222'::uuid, 80000),
    ('f432270b-271a-503b-bfd9-30a80933b9b7'::uuid, 200000),
    ('5c714e11-b5d9-5620-bdcf-0e927ba1bb8e'::uuid, 120000),
    ('d5ef267a-71de-5ac8-8de2-53b914068604'::uuid, 350000),
    ('84241dad-14ba-5eee-a551-0f040472b4ed'::uuid, 80000),
    ('718c1d6e-c33c-5008-becb-7ff273b15d70'::uuid, 300000),
    ('aa5ec740-cde4-5d36-8271-a4a3f768fb00'::uuid, 150000),
    ('3005cbbb-8f53-5469-a437-c23ffde2a0c5'::uuid, 60000),
    ('6217f7b7-9f7d-58bb-938c-4110dbe42232'::uuid, 150000),
    ('13d3c2b4-15a2-54db-88e3-fcb443cb6b12'::uuid, 70000),
    ('c3ca0e88-df72-576d-b9cc-7eca47ba7f67'::uuid, 80000),
    ('621904cc-2c2d-5166-83a4-b3122689410f'::uuid, 100000),
    ('40bcfbf6-2033-5298-afa7-322336908b11'::uuid, 20000),
    ('0b003767-70d6-5eb1-940f-a48af31d0818'::uuid, 150000),
    ('c9499791-3686-50dd-9e05-7a8a063411bb'::uuid, 25000),
    ('2c457db6-a8f8-538d-b6b4-ed172ddf8845'::uuid, 45000),
    ('57ce27bc-6f9b-58a3-b400-847d95d699d8'::uuid, 15000),
    ('7fb1a259-99d3-5595-96de-635f9a634974'::uuid, 200000),
    ('b49e9d1f-e2fc-5bdb-80d8-1eaafd400eab'::uuid, 600000),
    ('93726394-b845-585c-8c9e-9e6451c93f25'::uuid, 950000),
    ('3c2798de-dd95-5f3b-94c3-fb0e9de47d1f'::uuid, 1400000),
    ('3973181e-f89d-5be5-8f12-18614beadd61'::uuid, 30000)
), added AS (
    INSERT INTO catalog.price_versions (id, sub_service_id, amount_paisa, effective_from, created_by)
    SELECT gen_random_uuid(), w.sub_service_id, w.amount_paisa, now(), '00000000-0000-0000-0000-000000000000'
    FROM wanted w
    JOIN catalog.sub_services s ON s.id = w.sub_service_id
    LEFT JOIN catalog.price_versions p ON p.id = s.current_price_version_id
    WHERE p.amount_paisa IS DISTINCT FROM w.amount_paisa
    RETURNING id, sub_service_id
)
UPDATE catalog.sub_services s SET current_price_version_id = a.id FROM added a WHERE s.id = a.sub_service_id;

-- Bump the catalog version (expiring cached trees) and announce it, as every catalog write does.
WITH v AS (UPDATE catalog.catalog_version SET version = version + 1 RETURNING version)
INSERT INTO catalog.outbox (id, aggregate_id, event_name, payload, created_at, next_attempt_at)
SELECT gen_random_uuid(), 'catalog', 'catalog.CatalogChanged',
       jsonb_build_object('name', 'catalog.CatalogChanged', 'version', v.version), now(), now()
FROM v;
COMMIT;
